const rim=new THREE.DirectionalLight(0xe1efca,.24);rim.position.set(4,2,4);scene.add(rim);
// A procedural studio environment provides real specular/transmission illumination.
const studio=new THREE.Scene();studio.background=new THREE.Color(0xb4c39e);const environmentGeo=new THREE.SphereGeometry(1,20,12);
for(const [x,y,z,s,c] of [[-4,5,0,2.1,0xffffff],[3,2,-3,1.5,0xeeffd6],[1,-4,2,1.8,0x768b60]]){const m=new THREE.Mesh(environmentGeo,new THREE.MeshBasicMaterial({color:c}));m.position.set(x,y,z);m.scale.setScalar(s);studio.add(m);}const pmrem=new THREE.PMREMGenerator(renderer);const env=pmrem.fromScene(studio,.025);scene.environment=env.texture;scene.environmentIntensity=.03;pmrem.dispose();environmentGeo.dispose();studio.traverse(o=>o.material?.dispose());
